test("Studio applies configured high and low allocations, and defaults by tenant", () => {
  const catalog = {default:5, studios:new Map([["orchid",8], ["iris",2]])};
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(book("extra", 2)), {status:"full", id:"extra", remaining:1});
  assert.equal(dispatch(book("iris-big", 3, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("iris-ok", 2, {tenant:"iris"})).status, "booked");
  assert.equal(dispatch(book("default-big", 6, {tenant:"lily"})).status, "full");
  assert.equal(dispatch(book("default-ok", 5, {tenant:"lily"})).status, "booked");
  assert.equal(dispatch(book("archive-big", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(book("archive-ok", 5, {service:"archive"})).status, "booked");
  assert.equal(dispatch(book("another-day", 8, {day:"2025-04-03"})).status, "booked");
  assert.deepEqual(bookStudio(new Ledger(catalog), book("adapter", 7), catalog),
    {status:"booked", id:"adapter", remaining:1});
});

test("Studio preserves replay, cancellation, conflict and import accounting", () => {
  const dispatch = planner(readCatalog());
  const original = book("original", 8);
  assert.equal(dispatch(original).status, "booked");
  assert.equal(dispatch(original).status, "replay");
  assert.equal(dispatch({...original, units:7}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"original"}).status, "cancelled");
  assert.equal(dispatch(original).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"original"}).status, "replay");
  assert.equal(dispatch(book("replacement", 8)).status, "booked");
  assert.equal(dispatch({...book("backfill", 9, {day:"2025-04-03"}), action:"import"}).status, "imported");
  assert.deepEqual(dispatch(book("overflow", 1, {day:"2025-04-03"})),
    {status:"full", id:"overflow", remaining:0});
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:"2025-04-02"}), {units:8});
  assert.equal(apply(dispatch, book("invalid", -1)).status, "invalid");
